<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api } from '../../lib/api.js'
import { hasPermission } from '../../lib/auth.js'
const rows = ref([]); const flat = ref([]); const users = ref([]); const memberRows = ref([]); const dialog = ref(false); const memberDialog = ref(false); const editing = ref(null); const memberDepartment = ref('')
const form = reactive({ parentId: null, departmentCode: '', departmentName: '', leaderId: null, sortOrder: 0, status: true })
function flatten(items, result = []) { items.forEach(item => { result.push(item); flatten(item.children || [], result) }); return result }
async function load() { try { rows.value = await api.departments(); flat.value = flatten(rows.value); if (hasPermission('system.user.view')) { const data = await api.users({ page: 1, size: 100 }); users.value = data.list || [] } } catch (e) { ElMessage.error(e.message) } }
function open(row = null) { editing.value = row?.id || null; Object.assign(form, row ? { parentId: row.parentId, departmentCode: row.departmentCode, departmentName: row.departmentName, leaderId: row.leaderId, sortOrder: row.sortOrder, status: row.status } : { parentId: null, departmentCode: '', departmentName: '', leaderId: null, sortOrder: 0, status: true }); dialog.value = true }
async function save() { try { if (editing.value) await api.updateDepartment(editing.value, form); else await api.createDepartment(form); dialog.value = false; ElMessage.success('保存成功'); await load() } catch (e) { ElMessage.error(e.message) } }
async function openMembers(row) { try { const data = await api.users({ departmentId: row.id, page: 1, size: 100 }); memberRows.value = data.list || []; memberDepartment.value = row.departmentName; memberDialog.value = true } catch (e) { ElMessage.error(e.message) } }
async function toggle(row) { try { await ElMessageBox.confirm(`确认${row.status ? '停用' : '启用'}该部门吗？`); await api.departmentStatus(row.id, !row.status); await load() } catch (e) { if (e !== 'cancel') ElMessage.error(e.message) } }
onMounted(load)
</script>
<template>
<div class="page-heading"><div><h1>部门管理</h1><p class="muted">维护部门树和负责人。</p></div><el-button v-if="hasPermission('system.department.create')" type="primary" @click="open()">新增部门</el-button></div>
<el-card><el-table :data="rows" row-key="id" default-expand-all><el-table-column prop="departmentName" label="部门名称" /><el-table-column prop="departmentCode" label="部门编号" /><el-table-column prop="leaderName" label="负责人" /><el-table-column prop="memberCount" label="成员数" /><el-table-column label="状态"><template #default="{ row }"><el-tag :type="row.status ? 'success' : 'info'">{{ row.status ? '启用' : '停用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="240"><template #default="{ row }"><el-button link @click="openMembers(row)">成员</el-button><el-button v-if="hasPermission('system.department.update')" link type="primary" @click="open(row)">编辑</el-button><el-button v-if="hasPermission('system.department.disable')" link @click="toggle(row)">{{ row.status ? '停用' : '启用' }}</el-button></template></el-table-column></el-table></el-card>
<el-dialog v-model="dialog" :title="editing ? '编辑部门' : '新增部门'" width="480px"><el-form label-width="90px"><el-form-item label="上级部门"><el-select v-model="form.parentId" clearable style="width:100%"><el-option v-for="d in flat.filter(x => x.id !== editing)" :key="d.id" :label="d.departmentName" :value="d.id" /></el-select></el-form-item><el-form-item label="部门编号" required><el-input v-model="form.departmentCode" /></el-form-item><el-form-item label="部门名称" required><el-input v-model="form.departmentName" /></el-form-item><el-form-item label="负责人"><el-select v-model="form.leaderId" clearable filterable style="width:100%"><el-option v-for="u in users" :key="u.id" :label="`${u.realName}（${u.username}）`" :value="u.id" /></el-select></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortOrder" :min="0" /></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" /></el-form-item></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
<el-dialog v-model="memberDialog" :title="`${memberDepartment}成员`" width="620px"><el-table :data="memberRows"><el-table-column prop="employeeNo" label="工号" /><el-table-column prop="username" label="用户名" /><el-table-column prop="realName" label="姓名" /><el-table-column prop="phone" label="手机号" /><el-table-column label="状态"><template #default="{ row }"><el-tag :type="row.status ? 'success' : 'info'">{{ row.status ? '启用' : '停用' }}</el-tag></template></el-table-column></el-table></el-dialog>
</template>
